// 화면을 갈아타면 읽던 자리·스크롤·재생 상태가 다 날아간다. 그래서 별도 화면이 아니라
// 읽기 위에 얹는 창으로 만들고, 닫으면 곧바로 읽던 문장으로 돌아온다.
let wkList=[], wkIdx=0, wkWord="", wkStrokes=[], wkDrawing=false, wkCtx=null, wkOrder=2;
function wkCur(){ return wkList[wkIdx]||null; }
function wkFit(){
  const cv=$("wkCv"), box=$("wkBox"); if(!cv||!box) return false;
  const r=box.getBoundingClientRect(); if(!r.width||!r.height) return false;
  const dpr=window.devicePixelRatio||1;
  cv.width=Math.round(r.width*dpr); cv.height=Math.round(r.height*dpr);
  wkCtx=cv.getContext("2d"); wkCtx.setTransform(dpr,0,0,dpr,0,0);
  wkCtx.lineCap="round"; wkCtx.lineJoin="round";
  wkRedraw(); return true;
}
function wkFitSoon(){ if(wkFit()) return; requestAnimationFrame(()=>{ if(!wkFit()) setTimeout(wkFit,140); }); }
function wkRedraw(){
  if(!wkCtx) return;
  const cv=$("wkCv"); wkCtx.save(); wkCtx.setTransform(1,0,0,1,0,0);
  wkCtx.clearRect(0,0,cv.width,cv.height); wkCtx.restore();
  const ink=getComputedStyle(document.documentElement).getPropertyValue("--ink").trim()||"#2b2723";
  wkStrokes.forEach(st=>{
    if(!st.p.length) return;
    wkCtx.strokeStyle=ink; wkCtx.lineWidth=st.w;
    wkCtx.beginPath(); wkCtx.moveTo(st.p[0][0],st.p[0][1]);
    for(let i=1;i<st.p.length;i++) wkCtx.lineTo(st.p[i][0],st.p[i][1]);
    if(st.p.length===1) wkCtx.lineTo(st.p[0][0]+.1,st.p[0][1]+.1);
    wkCtx.stroke();
  });
}
function wkPt(e){ const r=$("wkCv").getBoundingClientRect(); return [e.clientX-r.left, e.clientY-r.top]; }
function wkUndo(){ wkStrokes.pop(); wkRedraw(); }
function wkClear(){ wkStrokes=[]; wkRedraw(); }
async function wkRenderOrder(){
  const box=$("wkSvg"); if(!box) return;
  box.innerHTML=""; box.classList.add("off");
  const c=wkCur(); if(!c || wkOrder===0) return;
  const svg=await kvgFetch(c.ch);
  if(!svg){ $("wkFt").textContent="이 글자는 획순 데이터가 없어요"; return; }
  box.appendChild(document.importNode(svg,true));
  box.classList.remove("off");
  [...box.querySelectorAll("path")].forEach(p=>p.style.opacity = wkOrder===1 ? ".10" : "");
}
function wkOrderCycle(){
  wkOrder=(wkOrder+1)%3;
  $("wkOrderBtn").textContent = wkOrder===0?"획순 끄기":wkOrder===1?"획순 번호":"획순 번호+선";
  wkRenderOrder();
}
let _wkAnim=0;
async function wkPlay(){
  const box=$("wkSvg"); if(!wkCur()) return;
  if(wkOrder===0){ wkOrder=2; $("wkOrderBtn").textContent="획순 번호+선"; }
  await wkRenderOrder();
  const paths=[...box.querySelectorAll("path")]; if(!paths.length) return;
  const tk=++_wkAnim, texts=[...box.querySelectorAll("text")];
  texts.forEach(t=>t.style.opacity="0");
  paths.forEach(p=>{ const L=p.getTotalLength(); p.style.transition="none";
    p.style.strokeDasharray=L; p.style.strokeDashoffset=L; p.style.opacity="1"; });
  for(let i=0;i<paths.length;i++){
    if(tk!==_wkAnim) return;
    const p=paths[i], L=p.getTotalLength(), dur=Math.max(260,Math.min(880,L*9));
    p.style.transition=`stroke-dashoffset ${dur}ms ease-in-out`; p.style.strokeDashoffset=0;
    if(texts[i]) texts[i].style.opacity="1";
    await new Promise(r=>setTimeout(r,dur+100));
  }
}
function wkLoad(){
  const c=wkCur(); if(!c) return;
  $("wkCh").textContent=c.ch;
  $("wkKo").textContent=c.ko||"";
  $("wkTpl").textContent=c.ch;
  $("wkPos").textContent = wkWord ? `「${wkWord}」 ${wkIdx+1} / ${wkList.length}` : `${wkIdx+1} / ${wkList.length}`;
  $("wkPrev").disabled = wkIdx<=0;
  $("wkNext").disabled = wkIdx>=wkList.length-1;
  const n=(wrLog()["book|"+c.ch]|0);
  $("wkFt").innerHTML = n? `이 글자 <b>${n}번</b> 썼어요` : "칸 안에 손가락으로 따라 써보세요";
  wkClear(); wkRenderOrder();
}
function wkGo(d){ const i=wkIdx+d; if(i<0||i>=wkList.length) return; wkIdx=i; wkLoad(); }
function wkOK(){
  const c=wkCur(); if(!c) return;
  if(!wkStrokes.length){ toast("먼저 한 번 써보세요"); return; }
  const o=wrLog(); const k="book|"+c.ch; o[k]=(o[k]|0)+1; wrSave(o);
  renderWrBar(); try{sfx("ok");}catch(e){}
  if(wkIdx<wkList.length-1){ toast("👏 좋아요! 다음 글자"); wkIdx++; wkLoad(); }
  else { toast("👏 다 썼어요 — 이어서 읽어요"); setTimeout(closeWritePop,600); }
}
// 단어의 한자를 전부 싣되 누른 글자부터 — 팝업이라 읽던 자리는 그대로 남는다
function openWritePop(word, start){
  const I=rdBuildIndex();
  const chs=[...new Set(String(word||"").match(/[一-鿿]/g)||[])];
  if(!chs.length){ toast("이 단어엔 한자가 없어요"); return; }
  wkList=chs.map(ch=>{ const ko=I.byK.get(ch)||I.byW.get(ch)||"";
    return {ch, ko:String(ko).split(/[,，·]/)[0].trim()}; });
  wkWord = chs.length>1 ? String(word) : "";
  wkIdx=Math.max(0,Math.min(chs.length-1,start|0));
  closeWordPop();
  $("wkPop").classList.add("on"); $("wkBd").classList.add("on");
  const cv=$("wkCv");
  if(cv && !cv._wired){
    cv._wired=true;
    cv.addEventListener("pointerdown",e=>{ e.preventDefault(); try{cv.setPointerCapture(e.pointerId);}catch(_){}
      if(!wkCtx) wkFit(); wkDrawing=true; wkStrokes.push({w:10,p:[wkPt(e)]}); wkRedraw(); });
    cv.addEventListener("pointermove",e=>{ if(!wkDrawing) return; e.preventDefault();
      wkStrokes[wkStrokes.length-1].p.push(wkPt(e)); wkRedraw(); });
    ["pointerup","pointercancel","pointerleave"].forEach(t=>cv.addEventListener(t,()=>{wkDrawing=false;}));
    window.addEventListener("resize",()=>{ if($("wkPop").classList.contains("on")) wkFitSoon(); });
  }
  wkOrder=2; $("wkOrderBtn").textContent="획순 번호+선";
  wkLoad(); wkFitSoon();
}
function closeWritePop(){
  _wkAnim++; wkDrawing=false;
  $("wkPop").classList.remove("on"); $("wkBd").classList.remove("on");
}
